/**
 *
 *
 * Simple events emitter.
 *
 * ## Installation
 *
 * ```sh
 * npm install @enkaku/event
 * ```
 *
 * @module event
 */ export class EventEmitter {
    #listeners = new Map();
    on(name, listener, options) {
        const filter = options?.filter;
        const wrappedListener = filter ? (data)=>{
            if (filter(data)) {
                return listener(data);
            }
        } : (data)=>{
            return listener(data);
        };
        let listeners = this.#listeners.get(name);
        if (!listeners) {
            listeners = new Set();
            this.#listeners.set(name, listeners);
        }
        listeners.add(wrappedListener);
        const off = ()=>{
            listeners.delete(wrappedListener);
        };
        const signal = options?.signal;
        if (signal) {
            if (signal.aborted) {
                off();
            } else {
                signal.addEventListener('abort', ()=>off(), {
                    once: true
                });
            }
        }
        return off;
    }
    once(name, options) {
        return new Promise((resolve, reject)=>{
            const signal = options?.signal;
            if (signal?.aborted) {
                reject(signal.reason);
                return;
            }
            const onAbort = signal ? ()=>{
                off();
                reject(signal.reason);
            } : undefined;
            const off = this.on(name, (data)=>{
                off();
                if (onAbort) {
                    signal?.removeEventListener('abort', onAbort);
                }
                resolve(data);
            }, {
                filter: options?.filter
            });
            if (onAbort) {
                signal?.addEventListener('abort', onAbort, {
                    once: true
                });
            }
        });
    }
    async emit(name, data) {
        const listeners = this.#listeners.get(name);
        if (!listeners || listeners.size === 0) return;
        const results = await Promise.allSettled([
            ...listeners
        ].map((fn)=>{
            try {
                return fn(data);
            } catch (err) {
                return Promise.reject(err);
            }
        }));
        const errors = results.filter((r)=>r.status === 'rejected').map((r)=>r.reason);
        if (errors.length === 1) throw errors[0];
        if (errors.length > 1) throw new AggregateError(errors);
    }
    readable(name, options = {}) {
        const abortController = new AbortController();
        const signal = options.signal ? AbortSignal.any([
            options.signal,
            abortController.signal
        ]) : abortController.signal;
        let isClosed = false;
        return new ReadableStream({
            start: (controller)=>{
                if (signal.aborted) {
                    isClosed = true;
                    controller.close();
                    return;
                }
                const off = this.on(name, (data)=>controller.enqueue(data), {
                    filter: options.filter,
                    signal
                });
                signal.addEventListener('abort', ()=>{
                    off();
                    if (!isClosed) {
                        isClosed = true;
                        controller.close();
                    }
                });
            },
            cancel () {
                isClosed = true;
                abortController.abort();
            }
        });
    }
    writable(name) {
        return new WritableStream({
            write: async (data)=>{
                await this.emit(name, data);
            }
        });
    }
}
